def case(gid,cid,md,me,td,te,ad,ae,fd,fe,criteria,mode='synthetic_analysis',routes=None):
    cid=cid.lower()
    brief=dict(id=cid,taskDemandDe=md+' '+td,taskDemandEn=me+' '+te,expectedPerformanceDe=ad,expectedPerformanceEn=ae,understandingFocusDe=fd,understandingFocusEn=fe)
    assert all(len(v)<=2000 for k,v in brief.items() if isinstance(v,str)),(gid,cid,'overlong field')
    row=dict(goalId=gid,case=brief,materialAndData=dict(de=md,en=me),modelAnswer=dict(de=ad,en=ae),rubric=dict(maximumPoints=len(criteria),criteria=[dict(points=1,aspectDe=d,aspectEn=e)for d,e in criteria],fullCreditEvidenceDe=ad,fullCreditEvidenceEn=ae),assessmentMethodDe='Bewertet wird die selbstständig vorgelegte chemische Begründung/Rechnung bzw. die ausdrücklich verlangte reale Handlung mit Originalprotokoll. Vorgelegte synthetische Daten und Modellantworten sind keine beobachtete Lernendenleistung.',assessmentMethodEn='Assess the independently submitted chemical reasoning/calculation or explicitly required actual action with its original record. Supplied synthetic data/model answers are not observed learner performance.',evidenceMode=mode,syntheticFixture=mode=='synthetic_analysis',sourceRouteRequirements=routes or [],observedLearnerWork=None,actualLabExecutionClaimed=False,humanApproval=False,humanTrial=False)
    cases.append(row)
    p=profiles.setdefault(gid,dict(archetype='concept',expectations=[],coverageExpectations=dict(requiredExpectationIds=[],alternativeExpectationGroups=[],minimumIndependentDemonstrations=2,freshVariationRequired=True,independentTransferRequired=True),variationAxes=[dict(id='chemically-relevant-conditions',textDe='Die vollständig gebundenen Fälle wechseln Reaktion, Systemgrenze, Temperatur, Aggregatzustand, Stoffmengen-/Energiebasis, Messverfahren oder Zusammensetzung. Tatsächliche Durchführung bleibt dort erforderlich, wo der konkrete Quellenoperator sie verlangt.',textEn='The bound cases vary reaction, system boundary, temperature, phase, amount/energy basis, method or composition. Actual execution remains required where the specific source operator demands it.')],applicationCaseBriefs=[]))
    eid='expectation-'+cid;p['expectations'].append(dict(id=eid,essentialUnderstandingDe=fd,essentialUnderstandingEn=fe,observablePerformanceDe=ad,observablePerformanceEn=ae));p['coverageExpectations']['requiredExpectationIds'].append(eid);p['applicationCaseBriefs'].append(brief)

# 801790: energy conservation, explicit sign convention, matter transport and pV work.
i='801790f9-be3a-51fe-9b0f-3452c1bba887'
case(i,'system-and-energy-boundaries',
 'Synthetische Systemkarten: A = offenes kochendes Wasser mit austretendem Dampf; B = dichtes Reaktionsgefäß mit beweglichem Kolben; C = ideales vollständig abgeschirmtes Gefäß. Für B: zugeführte Wärme Q=+1200 J, an der Umgebung geleistete Arbeit W_on=-350 J. Vorzeichen: Übertragung ins System positiv.',
 'Synthetic system cards: A = open boiling water with escaping steam; B = sealed reaction vessel with a movable piston; C = an ideal fully insulated vessel. For B: heat supplied Q=+1200 J; work done on surroundings W_on=-350 J. Transfers into the system are positive.',
 'Ordne offen/geschlossen/isoliert zu, berechne für B die Änderung der inneren Energie und erkläre Energieverbrauch. Begründe, warum bei A zusätzlich der Energieinhalt transportierter Materie und bei C eine mögliche Temperaturänderung trotz konstantem Gesamt-U zu beachten sind.',
 'Classify open/closed/isolated, calculate B\'s internal-energy change and interpret energy consumption. Explain why A additionally needs energy transported by matter and why C may change temperature while total U stays constant.',
 'A ist offen, B geschlossen (kein Stoffaustausch, Energieaustausch möglich), C ideal isoliert. Für das geschlossene B gilt ΔU=Q+W_on=850 J. Wärme/Arbeit sind Übertragungsgrößen, U eine Zustandsgröße. Bei A trägt entweichender Dampf Energie über die Systemgrenze; Q+W allein ist keine vollständige Bilanz des offenen Kontrollvolumens. Bei C gilt ΔU=0 für das Gesamtsystem, obwohl chemische Energie in thermische Energie übergehen und die Temperatur steigen kann. Energie wird umgewandelt/übertragen, nicht vernichtet; nur Energieänderungen werden bestimmt.',
 'A is open, B closed (no matter transfer; energy transfer possible), C ideally isolated. For closed B, ΔU=Q+W_on=850 J. Heat/work are transfer quantities; U is a state quantity. Escaping steam in A carries energy across the boundary, so Q+W alone is not the complete open-control-volume balance. Total ΔU=0 in C, although chemical energy can become thermal energy and temperature can rise. Energy is transformed/transferred, not destroyed; measurements determine changes.',
 'Systemgrenze, Energieerhaltung und Vorzeichen zusammen erklären.','Explain system boundaries, energy conservation and signs together.',
 [('Alle drei Systemarten korrekt zuordnen.','Correctly classify all three systems.'),('850 J mit Q+W_on und der angegebenen Konvention begründen.','Justify 850 J using Q+W_on and the given convention.'),('Materietransport bei offenem System berücksichtigen.','Account for matter transport in an open system.'),('Konstantes Gesamt-U von konstantem Temperaturwert unterscheiden.','Distinguish constant total U from constant temperature.')])
case(i,'isobaric-isochoric-work',
 'Synthetischer geschlossener Gasprozess: Q=+500 J, konstanter äußerer Druck p_ext=100 kPa, Volumenzunahme ΔV=2,00 L, ausschließlich Volumenarbeit. Gegenfall: starres Gefäß mit ebenfalls Q=+500 J. Für die jeweilige Bilanz gelten W_on=-p_ext ΔV und H=U+pV.',
 'Synthetic closed-gas process: Q=+500 J, constant external pressure p_ext=100 kPa, volume increase ΔV=2.00 L, only pressure-volume work. Contrast: a rigid vessel also receives Q=+500 J. Use W_on=-p_ext ΔV and H=U+pV.',
 'Berechne W_on und ΔU, erläutere unter den genannten isobaren Bedingungen ΔH=Q_p und vergleiche mit isochorer Prozessführung. Zeichne eine beschriftete Energiebilanz; erkläre, warum gleiche zugeführte Wärme hier nicht gleiche ΔU bedeutet.',
 'Calculate W_on and ΔU, explain ΔH=Q_p under the stated constant-pressure conditions and compare a constant-volume process. Draw a labelled energy balance and explain why equal supplied heat does not give equal ΔU here.',
 '100000 Pa×0,00200 m³=200 J. Expansion: W_on=-200 J; ΔU=+300 J. Bei gleichem konstantem System-/Außendruck und nur pV-Arbeit gilt ΔH=ΔU+pΔV=500 J=Q_p. Im starren Gefäß ist ΔV=0, W_on=0 und ΔU=500 J=Q_v. Der Unterschied folgt aus Arbeitsübertragung, nicht aus Energieverlust. Die Skizze zeigt 500 J hinein, 200 J Arbeit hinaus und 300 J U-Zunahme. Die beiden Prozesse müssen nicht denselben Endzustand haben; U/H-Zuordnung gilt unter den jeweils angegebenen Bedingungen.',
 '100000 Pa×0.00200 m³=200 J. Expansion gives W_on=-200 J and ΔU=+300 J. With equal constant system/external pressure and only pV work, ΔH=ΔU+pΔV=500 J=Q_p. The rigid vessel has ΔV=0, W_on=0 and ΔU=500 J=Q_v. Work transfer, not destroyed energy, explains the difference. The sketch shows 500 J in, 200 J work out and a 300 J U increase. The processes need not have identical final states; the U/H relations depend on the stated conditions.',
 'Isochore und isobare Bilanz sowie Wärme/Volumenarbeit unterscheiden.','Distinguish constant-volume/pressure balances and heat/pV work.',
 [('Druck und Volumen in SI-Einheiten umrechnen.','Convert pressure and volume to SI units.'),('W_on=-200 J und ΔU=300 J berechnen.','Calculate W_on=-200 J and ΔU=300 J.'),('ΔH=Q_p und ΔU=Q_v bedingungsgebunden erklären.','Explain conditional ΔH=Q_p and ΔU=Q_v.'),('Beschriftete Bilanz und unterschiedliche Endzustände berücksichtigen.','Use a labelled balance and recognise different final states.')])

