maps={};mapdeltas=[]
for row in raw['rows']:
    sg=row['wholeSourceGoal'];fix=fixes.get(sg['id'])
    if not fix:continue
    path=row['mappingPath'];m=maps.setdefault(path,read(R/path));ix=row['mappingDecisionIndex'];before=copy.deepcopy(m['decisions'][ix]);after=m['decisions'][ix]
    after['canonicalGoalIds']=[i for i in before['canonicalGoalIds']if i not in fix['remove']]+[i for i in fix['add']if i not in before['canonicalGoalIds']]
    after['rationale']='Inaktiver Autorenkorrekturvorschlag aus vollständiger wörtlicher Quelle: '+fix['why'];after['reviewedAt']='2026-10-12';after['reviewer']='Codex author proposal; independent source review pending'
    for mapping in m.get('mappings',[]):
        if mapping.get('sourceGoalId')==sg['id']:
            if 'canonicalGoalIds' in mapping:mapping['canonicalGoalIds']=after['canonicalGoalIds']
            elif 'canonicalGoalId' in mapping:raise RuntimeError('Singular derived mapping requires explicit handling')
    mapdeltas.append(dict(mappingPath=path,sourceGoalId=sg['id'],before=before,after=copy.deepcopy(after),wholeSourceGoal=sg,sourceCourseLevel=sg.get('courseLevel'),wholeSourceClearanceGranted=False))
